const E = (id, name, en, slot, equip, prim, sec, cues, o = {}) => ({
  id, name, en, slot, equip, prim, sec, cues,
  cat: o.cat || 'strength',
  load: o.load || 'kg',
  inc: o.inc ?? 2.5,
  reps: o.reps || [8, 12],
  presc: o.presc || '',
  iv: o.iv || null, // Intervall-Uhr: warm/cool (s), work/rest (s), rounds, sets, setRest (s)
});

